  var shots = [
    { src: 'data:image/jpeg;base64,', cap: 'Игровой мир TPL' },
    { src: 'data:image/jpeg;base64,', cap: 'Наши составы' },
    { src: 'data:image/jpeg;base64,', cap: 'Железнодорожная карта TPL' },
    { src: 'data:image/jpeg;base64,', cap: 'Скриншот с сервера' },
    { src: 'data:image/jpeg;base64,', cap: 'Скриншот с сервера' },
    { src: 'data:image/jpeg;base64,', cap: 'Скриншот с сервера' },
    { src: 'data:image/jpeg;base64,', cap: 'Скриншот с сервера' }
  ];
  var sc = document.getElementById('screens');
  shots.forEach(function (s) {
    var d = document.createElement('div');
    d.className = 'screen';
    d.innerHTML = '<img src="' + s.src + '" alt="' + s.cap + '"><div class="cap">' + s.cap + '</div>';
    d.addEventListener('click', function () {
      document.getElementById('lightbox').querySelector('img').src = s.src;
      document.getElementById('lightbox').classList.add('show');
    });
    sc.appendChild(d);
  });

  var lb = document.getElementById('lightbox');
  lb.addEventListener('click', function () { lb.classList.remove('show'); });
  document.querySelector('#lightbox .close').addEventListener('click', function (e) { e.stopPropagation(); lb.classList.remove('show'); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') lb.classList.remove('show'); });

  document.getElementById('playBtn').addEventListener('click', function (e) {
    e.preventDefault();
    var ip = 'molecule-adopting.tun.ply.gg:25565';
    function showToast() {
      var t = document.getElementById('toast');
      t.classList.add('show');
      setTimeout(function () { t.classList.remove('show'); }, 4000);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(ip).then(showToast).catch(showToast);
    } else {
      var ta = document.createElement('textarea');
      ta.value = ip;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (err) {}
      document.body.removeChild(ta);
      showToast();
    }
  });
